// Package audio provides dynamic EQ de-essing to detect and suppress harsh sibilance
// ('s', 'sh', 'ch', 'ts' sounds in 6kHz-8kHz band) generated by neural vocal synthesizers.
package audio

import (
	"encoding/json"
	"math"
)

// DeEsserConfig configures the dynamic sibilance controller.
type DeEsserConfig struct {
	CenterFreqHz    float64 `json:"center_freq_hz"`    // Sibilance center frequency, default: 7000 Hz
	BandwidthHz     float64 `json:"bandwidth_hz"`      // Filter detection bandwidth, default: 2000 Hz (6kHz..8kHz)
	ThresholdDbFS   float64 `json:"threshold_dbfs"`    // Trigger threshold, default: -20.0 dBFS
	MaxReductionDb  float64 `json:"max_reduction_db"`  // Maximum dynamic attenuation cap, default: 8.0 dB
	Ratio           float64 `json:"ratio"`             // Compression slope ratio, default: 4.0
	AttackMs        float64 `json:"attack_ms"`         // Detector attack time, default: 1.0 ms
	ReleaseMs       float64 `json:"release_ms"`        // Detector release time, default: 35.0 ms
}

// DefaultDeEsserConfig provides broadcast-grade vocal de-essing parameters.
func DefaultDeEsserConfig() DeEsserConfig {
	return DeEsserConfig{
		CenterFreqHz:   7000.0,
		BandwidthHz:    2000.0,
		ThresholdDbFS:  -20.0,
		MaxReductionDb: 8.0,
		Ratio:          4.0,
		AttackMs:       1.0,
		ReleaseMs:      35.0,
	}
}

// DeEsserResult holds the processed PCM buffer and de-essing telemetry.
type DeEsserResult struct {
	ProcessedBuffer       *PCMBuffer `json:"-"`
	MaxReductionAppliedDb float64    `json:"max_reduction_applied_db"` // Maximum dB reduction observed
	SibilancePeakBeforeDb float64    `json:"sibilance_peak_before_db"`
	SibilancePeakAfterDb  float64    `json:"sibilance_peak_after_db"`
	TargetSuppressionMet  bool       `json:"target_suppression_met"`    // True if >= 4.0 dB reduction achieved
	SibilantEventsCount   int        `json:"sibilant_events_count"`
}

// DynamicDeEsser implements dynamic spectral notching on vocal sibilance.
type DynamicDeEsser struct {
	cfg DeEsserConfig
}

// NewDynamicDeEsser creates a new de-esser.
func NewDynamicDeEsser(cfg DeEsserConfig) *DynamicDeEsser {
	if cfg.CenterFreqHz <= 1000.0 || cfg.CenterFreqHz >= 16000.0 {
		cfg.CenterFreqHz = 7000.0
	}
	if cfg.BandwidthHz <= 200.0 {
		cfg.BandwidthHz = 2000.0
	}
	if cfg.ThresholdDbFS >= 0.0 {
		cfg.ThresholdDbFS = -20.0
	}
	if cfg.MaxReductionDb <= 0.0 {
		cfg.MaxReductionDb = 8.0
	}
	if cfg.Ratio < 1.5 {
		cfg.Ratio = 4.0
	}
	if cfg.AttackMs <= 0.1 {
		cfg.AttackMs = 1.0
	}
	if cfg.ReleaseMs <= 1.0 {
		cfg.ReleaseMs = 35.0
	}
	return &DynamicDeEsser{cfg: cfg}
}

// Process detects and dynamically attenuates sibilance peaks in the 6kHz-8kHz band.
func (de *DynamicDeEsser) Process(input *PCMBuffer) (*DeEsserResult, error) {
	if input == nil {
		return nil, ErrNilPCMBuffer
	}
	if input.NumSamples == 0 || input.Channels == 0 || len(input.Samples) == 0 {
		return nil, ErrEmptyPCMBuffer
	}

	numSamples := input.NumSamples
	sampleRate := input.SampleRate
	channels := input.Channels

	fc := de.cfg.CenterFreqHz
	bw := de.cfg.BandwidthHz
	fLow := fc - bw/2.0
	fHigh := fc + bw/2.0

	thresholdLinear := math.Pow(10.0, de.cfg.ThresholdDbFS/20.0)
	attackCoeff := math.Exp(-1.0 / ((de.cfg.AttackMs / 1000.0) * float64(sampleRate)))
	releaseCoeff := math.Exp(-1.0 / ((de.cfg.ReleaseMs / 1000.0) * float64(sampleRate)))

	outSamples := make([][]float64, channels)
	var maxGRDb float64
	var sibPeakBefore, sibPeakAfter float64
	var eventCount int
	inEvent := false

	for ch := 0; ch < channels; ch++ {
		src := input.Samples[ch]
		dst := make([]float64, numSamples)

		// Extract sibilance band (6kHz..8kHz) via Bandpass = Highpass(fLow) -> Lowpass(fHigh)
		hp := highpassIIR(src, sampleRate, fLow)
		sibBand := lowpassIIR(hp, sampleRate, fHigh)

		// Envelope follower and dynamic gain computer
		env := 0.0
		for i := 0; i < numSamples; i++ {
			x := src[i]
			s := math.Abs(sibBand[i])

			if s > sibPeakBefore {
				sibPeakBefore = s
			}

			// Attack / Release envelope follower
			if s > env {
				env = attackCoeff*env + (1.0-attackCoeff)*s
			} else {
				env = releaseCoeff*env + (1.0-releaseCoeff)*s
			}

			// Calculate dynamic gain reduction
			gain := 1.0
			if env > thresholdLinear {
				if !inEvent {
					inEvent = true
					eventCount++
				}
				envDb := 20.0 * math.Log10(env)
				excessDb := envDb - de.cfg.ThresholdDbFS
				grDb := (excessDb * (1.0 - 1.0/de.cfg.Ratio))
				if grDb > de.cfg.MaxReductionDb {
					grDb = de.cfg.MaxReductionDb
				}
				if grDb > maxGRDb {
					maxGRDb = grDb
				}
				gain = math.Pow(10.0, -grDb/20.0)
			} else {
				inEvent = false
			}

			// Apply gain reduction specifically to the sibilance band component
			// dst = dry_outside_sibilance + (sibilance_component * dynamic_gain)
			nonSib := x - sibBand[i]
			processedSib := sibBand[i] * gain
			outVal := nonSib + processedSib

			dst[i] = outVal

			absAfter := math.Abs(processedSib)
			if absAfter > sibPeakAfter {
				sibPeakAfter = absAfter
			}
		}

		outSamples[ch] = dst
	}

	peakBeforeDb := toDbFS(sibPeakBefore)
	peakAfterDb := toDbFS(sibPeakAfter)
	peakReductionDb := peakBeforeDb - peakAfterDb

	outBuf := &PCMBuffer{
		Channels:   channels,
		SampleRate: sampleRate,
		NumSamples: numSamples,
		Samples:    outSamples,
	}

	return &DeEsserResult{
		ProcessedBuffer:       outBuf,
		MaxReductionAppliedDb: math.Round(maxGRDb*10) / 10,
		SibilancePeakBeforeDb: math.Round(peakBeforeDb*10) / 10,
		SibilancePeakAfterDb:  math.Round(peakAfterDb*10) / 10,
		TargetSuppressionMet:  maxGRDb >= 4.0 || peakReductionDb >= 4.0,
		SibilantEventsCount:   eventCount,
	}, nil
}

// ToJSON serializes de-esser telemetry.
func (r *DeEsserResult) ToJSON() (string, error) {
	b, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return "", err
	}
	return string(b), nil
}
